/**
 * Lightweight local Material Rounded vector icons replacing material-icons-extended (~50 MB raw DEX).
 * Core icons (ArrowBack, ArrowForward, Send, Check, CheckCircle, Home, KeyboardArrowDown, Refresh)
 * remain served by material-icons-core.
 */
object StudioIcons {

    private fun icon(
        name: String,
        paths: List<String>,
        autoMirror: Boolean = false,
        viewportSize: Float = 24f,
        translateY: Float = 0f
    ): ImageVector = ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = viewportSize,
        viewportHeight = viewportSize,
        autoMirror = autoMirror
    ).apply {
        val fill = SolidColor(Color.Black)
        if (translateY != 0f) {
            group(translationY = translateY) {
                for (d in paths) {
                    addPath(
                        pathData = PathParser().parsePathString(d).toNodes(),
                        pathFillType = PathFillType.NonZero,
                        fill = fill,
                        stroke = null,
                        strokeLineWidth = 1f,
                        strokeLineCap = StrokeCap.Butt,
                        strokeLineJoin = StrokeJoin.Bevel,
                        strokeLineMiter = 1f
                    )
                }
            }
        } else {
            for (d in paths) {
                addPath(
                    pathData = PathParser().parsePathString(d).toNodes(),
                    pathFillType = PathFillType.NonZero,
                    fill = fill,
                    stroke = null,
                    strokeLineWidth = 1f,
                    strokeLineCap = StrokeCap.Butt,
                    strokeLineJoin = StrokeJoin.Bevel,
                    strokeLineMiter = 1f
                )
            }
        }
    }.build()

